/// Uber-grind phase, animation table and pose-slew fields.
mod uber_input {
    pub const KIND: u32 = 4;
    pub const RIDER: u32 = 8;
    pub const HOLD_ANIM: u32 = 0x10;
    pub const LEAN_ANIM: u32 = 0x14;
    pub const INTERRUPT_ANIM: u32 = 0x18;
    pub const RELEASE_ANIM: u32 = 0x1c;
    pub const POSE: u32 = 0x238;
    pub const POSE_STEP: u32 = 0x23c;
    pub const POSE_TARGET: u32 = 0x240;
    pub const ANIM_SEQUENCE_SPEED: u32 = 0x90;
    pub const STANCE: u32 = 0x328;
    pub const METRIX: u32 = 0x790;
    /// gp-0x72d8: 1/31, scale for the signed pad axis.
    pub const GP_AXIS_SCALE: u32 = 0x72d8;
    /// gp-0x72d4: 0.058333337, entry pose step (3.5/60).
    pub const GP_ENTER_STEP: u32 = 0x72d4;
    /// gp-0x72d0: 0.058333337, ground pose step (3.5/60).
    pub const GP_GROUND_STEP: u32 = 0x72d0;
    /// gp-0x72cc: 0.058333337, rail pose step (3.5/60).
    pub const GP_RAIL_STEP: u32 = 0x72cc;
    /// gp-0x72c8: 0.1, pose magnitude selecting the lean animation.
    pub const GP_LEAN_THRESHOLD: u32 = 0x72c8;
    /// gp-0x72c4: 0.058333337, exit pose step (3.5/60).
    pub const GP_EXIT_STEP: u32 = 0x72c4;
}

/// `RiderUberGrindSub_HandleInput(sub, input)` (0x136508): advance the
/// enter/hold/exit animation phases and award the completed grind's boost.
/// Its four pose steps (rider +0x23c) are [`crate::tick::PER_TICK`] entries.
pub fn rider_uber_grind_sub_handle_input(c: &mut Cpu) {
    guest(c, |c| {
        const SAVED_RA: u32 = 0;
        const SAVED_ANIM_TABLE: u32 = 0x10;
        const SAVED_INPUT: u32 = 0x20;
        const SAVED_SUBSTATE: u32 = 0x30;
        const SAVED_F20: u32 = 0x40;
        c.cycles += 16;
        let frame = Frame::open(c, 0x50);
        c.g[A2][0] = 0;
        frame.save(c, S0, SAVED_SUBSTATE);
        frame.save(c, S1, SAVED_INPUT);
        c.g[S0][0] = c.g[A0][0];
        frame.save(c, S2, SAVED_ANIM_TABLE);
        c.g[S1][0] = c.g[A1][0];
        frame.save_ra(c, SAVED_RA);
        frame.save_fpr(c, 20, SAVED_F20);
        uber_grind_input(c)?;
        frame.restore(c, S0, SAVED_SUBSTATE);
        c.cycles += 6;
        frame.restore(c, S1, SAVED_INPUT);
        frame.restore(c, S2, SAVED_ANIM_TABLE);
        frame.restore_ra(c, SAVED_RA);
        frame.restore_fpr(c, 20, SAVED_F20);
        frame.close(c);
        Ok(())
    })
}

fn uber_grind_input(c: &mut Cpu) -> Flow {
    use uber_input::*;
    c.g[A1][0] = Addr(r32(c, S1)).lw(c);
    c.g[A0][0] = Addr(r32(c, S0)).off(RIDER).lw(c);
    c.g[A1][0] = sx(((r32(c, A1) as i32) >> 12) as u32);
    c.g[A1][0] &= 1;
    call_ptr(c, 0x0011_6120, 0x0013_6540)?;
    if c.g[V0][0] != 0 {
        return Ok(());
    }
    c.cycles += 10;
    c.g[V1][0] = Addr(r32(c, S0)).off(KIND).lw(c);
    c.g[A1][0] = 0x24;
    c.g[V0][0] = 0x460000;
    c.g[A0][0] = Addr(r32(c, S0)).off(RIDER).lw(c);
    c.mult(0, V1, V1, A1);
    // 0x45a038: uber-grind animation records, 0x24 bytes per kind.
    c.g[V0][0] = sx(r32(c, V0).wrapping_sub(0x5fc8));
    c.g[S2][0] = sx(r32(c, V1).wrapping_add(r32(c, V0)));
    call_ptr(c, 0x0010_6848, 0x0013_6568)?;
    let interrupted = c.g[V0][0] != 0;
    c.g[V0][0] = 1;
    if interrupted {
        c.cycles += 3;
        c.g[V1][0] = Addr(r32(c, S0)).lw(c);
        if c.g[V1][0] == c.g[V0][0] {
            c.cycles += 9;
            c.g[V0][0] = Addr(r32(c, S0)).off(RIDER).lw(c);
            c.g[A2][0] = 0;
            c.g[A1][0] = Addr(r32(c, S2)).off(INTERRUPT_ANIM).lw(c);
            c.g[AT][0] = sx(0xbf80_0000);
            c.mtc1(AT, 12);
            c.g[A0][0] = Addr(r32(c, V0)).off(RIDER_ANIM).lw(c);
            call_ptr(c, 0x0031_28e8, 0x0013_6598)?;
        }
        return Ok(());
    }
    c.cycles += 24;
    c.g[A1][0] = Addr(r32(c, S1)).lw(c);
    c.g[A0][0] = Addr(r32(c, S0)).off(RIDER).lw(c);
    c.g[A2][0] = sx(((r32(c, A1) as i32) >> 13) as u32);
    c.mtc1(0, 20);
    c.g[A1][0] = sx(((r32(c, A1) as i32) >> 14) as u32);
    c.g[A2][0] &= 1;
    c.g[A1][0] &= 1;
    call_ptr(c, 0x0011_4130, 0x0013_65c0)?;
    c.g[V0][0] = Addr(r32(c, S1)).lw(c);
    c.lwc1(0, r32(c, GP).wrapping_sub(GP_AXIS_SCALE));
    c.g[V0][0] = sx(r32(c, V0) << 3);
    c.g[A0][0] = Addr(r32(c, S0)).off(RIDER).lw(c);
    c.g[V0][0] = sx(((r32(c, V0) as i32) >> 26) as u32);
    c.mtc1(V0, 12);
    c.cvt_s_w(12, 12);
    c.mul_s(12, 12, 0);
    call_ptr(c, 0x0011_3f38, 0x0013_65e4)?;
    c.g[A0][0] = Addr(r32(c, S0)).off(RIDER).lw(c);
    c.mov_s(12, 20);
    c.mov_s(13, 20);
    call_ptr(c, 0x0011_3f88, 0x0013_65f4)?;
    c.g[V0][0] = Addr(r32(c, S0)).lw(c);
    if c.g[V0][0] == 0 {
        uber_grind_enter(c)?;
        c.cycles += 1;
    }
    c.g[V1][0] = Addr(r32(c, S0)).lw(c);
    c.cycles += 3;
    c.g[V0][0] = 1;
    if c.g[V1][0] == c.g[V0][0] {
        uber_grind_hold(c)?;
    } else {
        c.g[V1][0] = Addr(r32(c, S0)).lw(c);
    }
    c.cycles += 3;
    c.g[V0][0] = 2;
    if c.g[V1][0] == c.g[V0][0] {
        uber_grind_exit(c)?;
    }
    Ok(())
}

/// Start the holding animation once the entry animation is finished.
fn uber_grind_enter(c: &mut Cpu) -> Flow {
    use uber_input::*;
    c.cycles += 10;
    c.g[V1][0] = Addr(r32(c, S0)).off(RIDER).lw(c);
    c.g[A1][0] = 2;
    c.lwc1(0, r32(c, GP).wrapping_sub(GP_ENTER_STEP));
    c.swc1(20, r32(c, V1).wrapping_add(POSE_TARGET));
    c.swc1(0, r32(c, V1).wrapping_add(POSE_STEP));
    c.g[V0][0] = Addr(r32(c, S0)).off(RIDER).lw(c);
    c.g[A0][0] = Addr(r32(c, V0)).off(RIDER_ANIM).lw(c);
    call_ptr(c, 0x0031_2ae8, 0x0013_6620)?;
    let done = c.g[V0][0] != 0;
    c.g[A2][0] = 0;
    if done {
        c.cycles += 15;
        c.g[V0][0] = Addr(r32(c, S0)).off(RIDER).lw(c);
        c.g[A1][0] = Addr(r32(c, S2)).off(HOLD_ANIM).lw(c);
        c.g[AT][0] = sx(0xbf80_0000);
        c.mtc1(AT, 12);
        c.g[A0][0] = Addr(r32(c, V0)).off(RIDER_ANIM).lw(c);
        call_ptr(c, 0x0031_28e8, 0x0013_6640)?;
        c.g[V1][0] = Addr(r32(c, S0)).off(RIDER).lw(c);
        c.g[A1][0] = 2;
        c.g[A0][0] = Addr(r32(c, V1)).off(RIDER_ANIM).lw(c);
        call_ptr(c, 0x0031_1b20, 0x0013_6650)?;
        c.g[AT][0] = 0x3f80_0000;
        c.mtc1(AT, 0);
        c.g[V1][0] = 1;
        c.swc1(0, r32(c, V0).wrapping_add(ANIM_SEQUENCE_SPEED));
        Addr(r32(c, S0)).sw(c, c.g[V1][0]);
    }
    Ok(())
}

/// Choose the held pose or start the release animation when input changes.
fn uber_grind_hold(c: &mut Cpu) -> Flow {
    use uber_input::*;
    c.cycles += 6;
    c.g[V0][0] = Addr(r32(c, S1)).lw(c);
    c.g[V1][0] = Addr(r32(c, S0)).off(KIND).lw(c);
    c.g[V0][0] = sx(r32(c, V0) << 9);
    c.g[V0][0] = sx(((r32(c, V0) as i32) >> 24) as u32);
    let mut release = c.g[V0][0] != c.g[V1][0];
    if !release {
        c.cycles += 4;
        c.g[A0][0] = Addr(r32(c, S0)).off(RIDER).lw(c);
        call_ptr(c, 0x0011_fe98, 0x0013_6694)?;
        release = c.g[V0][0] == 0;
    }
    c.g[V0][0] = Addr(r32(c, S0)).off(RIDER).lw(c);
    if release {
        c.cycles += 16;
        c.g[A2][0] = 0;
        c.g[A1][0] = Addr(r32(c, S2)).off(RELEASE_ANIM).lw(c);
        c.g[AT][0] = sx(0xbf80_0000);
        c.mtc1(AT, 12);
        c.g[A0][0] = Addr(r32(c, V0)).off(RIDER_ANIM).lw(c);
        call_ptr(c, 0x0031_28e8, 0x0013_66b4)?;
        c.g[V1][0] = Addr(r32(c, S0)).off(RIDER).lw(c);
        c.g[A1][0] = 2;
        c.g[A0][0] = Addr(r32(c, V1)).off(RIDER_ANIM).lw(c);
        call_ptr(c, 0x0031_1b20, 0x0013_66c4)?;
        c.g[AT][0] = 0x3f80_0000;
        c.mtc1(AT, 0);
        c.g[V1][0] = 2;
        c.swc1(0, r32(c, V0).wrapping_add(ANIM_SEQUENCE_SPEED));
        Addr(r32(c, S0)).sw(c, c.g[V1][0]);
    } else {
        c.cycles += 6;
        c.g[A1][0] = 2;
        c.g[A0][0] = Addr(r32(c, V0)).off(RIDER_ANIM).lw(c);
        call_ptr(c, 0x0031_2aa0, 0x0013_66e8)?;
        c.g[V1][0] = Addr(r32(c, S2)).off(INTERRUPT_ANIM).lw(c);
        let interrupted_anim = c.g[V0][0] == c.g[V1][0];
        c.g[A1][0] = 2;
        if interrupted_anim {
            c.cycles += 5;
            c.g[V0][0] = Addr(r32(c, S0)).off(RIDER).lw(c);
            c.g[A0][0] = Addr(r32(c, V0)).off(RIDER_ANIM).lw(c);
            call_ptr(c, 0x0031_2ae8, 0x0013_6700)?;
            if c.g[V0][0] == 0 {
                c.g[V1][0] = Addr(r32(c, S0)).lw(c);
                return Ok(());
            }
        }
        uber_grind_pose(c)?;
    }
    c.cycles += 1;
    c.g[V1][0] = Addr(r32(c, S0)).lw(c);
    Ok(())
}

fn uber_grind_pose(c: &mut Cpu) -> Flow {
    use uber_input::*;
    c.cycles += 5;
    c.g[A0][0] = Addr(r32(c, S0)).off(RIDER).lw(c);
    call_ptr(c, 0x0011_fe98, 0x0013_6710)?;
    c.g[V1][0] = 4;
    let railslide = c.g[V0][0] == c.g[V1][0];
    if railslide {
        c.g[V1][0] = Addr(r32(c, S0)).off(RIDER).lw(c);
        c.cycles += 5;
        c.lwc1(1, r32(c, GP).wrapping_sub(GP_RAIL_STEP));
        c.g[V0][0] = Addr(r32(c, V1)).off(BUMP_RIDER_OWNER).lw(c);
        // RiderBase +0xc8: rail pose target; field name unresolved.
        c.lwc1(0, r32(c, V0).wrapping_add(0xc8));
        c.swc1(1, r32(c, V1).wrapping_add(POSE_STEP));
        c.swc1(0, r32(c, V1).wrapping_add(POSE_TARGET));
    } else {
        c.cycles += 5;
        c.g[V0][0] = Addr(r32(c, S0)).off(RIDER).lw(c);
        c.lwc1(0, r32(c, GP).wrapping_sub(GP_GROUND_STEP));
        Addr(r32(c, V0)).off(POSE_TARGET).sw(c, 0);
        c.swc1(0, r32(c, V0).wrapping_add(POSE_STEP));
    }
    c.cycles += 13;
    c.g[V0][0] = Addr(r32(c, S0)).off(RIDER).lw(c);
    c.g[A1][0] = 2;
    c.g[A0][0] = Addr(r32(c, V0)).off(RIDER_ANIM).lw(c);
    call_ptr(c, 0x0031_2aa0, 0x0013_6754)?;
    c.g[V1][0] = c.g[V0][0];
    c.lwc1(1, r32(c, GP).wrapping_sub(GP_LEAN_THRESHOLD));
    c.g[V0][0] = Addr(r32(c, S0)).off(RIDER).lw(c);
    c.lwc1(0, r32(c, V0).wrapping_add(POSE));
    c.abs_s(0, 0);
    c.c_lt_s(0, 1);
    if c.fcc() {
        c.cycles += 1;
        c.g[A1][0] = Addr(r32(c, S2)).off(HOLD_ANIM).lw(c);
    } else {
        c.g[A1][0] = Addr(r32(c, S2)).off(LEAN_ANIM).lw(c);
    }
    c.cycles += 2;
    let same_anim = c.g[A1][0] == c.g[V1][0];
    c.g[A2][0] = 0;
    if !same_anim {
        c.cycles += 5;
        c.g[V0][0] = Addr(r32(c, S0)).off(RIDER).lw(c);
        c.g[AT][0] = sx(0xbf80_0000);
        c.mtc1(AT, 12);
        c.g[A0][0] = Addr(r32(c, V0)).off(RIDER_ANIM).lw(c);
        call_ptr(c, 0x0031_28e8, 0x0013_6798)?;
    }
    Ok(())
}

/// Wait for the release animation, restore the ordinary substate, then score.
fn uber_grind_exit(c: &mut Cpu) -> Flow {
    use uber_input::*;
    c.cycles += 11;
    c.g[V1][0] = Addr(r32(c, S0)).off(RIDER).lw(c);
    c.g[A1][0] = 2;
    c.lwc1(0, r32(c, GP).wrapping_sub(GP_EXIT_STEP));
    Addr(r32(c, V1)).off(POSE_TARGET).sw(c, 0);
    c.swc1(0, r32(c, V1).wrapping_add(POSE_STEP));
    c.g[V0][0] = Addr(r32(c, S0)).off(RIDER).lw(c);
    c.g[A0][0] = Addr(r32(c, V0)).off(RIDER_ANIM).lw(c);
    call_ptr(c, 0x0031_1ae8, 0x0013_67c8)?;
    c.g[V1][0] = 0x15;
    let release_anim = c.g[V0][0] == c.g[V1][0];
    c.g[A1][0] = 2;
    if release_anim {
        c.cycles += 5;
        c.g[V0][0] = Addr(r32(c, S0)).off(RIDER).lw(c);
        c.g[A0][0] = Addr(r32(c, V0)).off(RIDER_ANIM).lw(c);
        call_ptr(c, 0x0031_2ae8, 0x0013_67e0)?;
        let done = c.g[V0][0] != 0;
        c.g[A1][0] = 2;
        if !done {
            c.cycles += 8;
            c.g[V0][0] = Addr(r32(c, S0)).off(RIDER).lw(c);
            c.g[A0][0] = Addr(r32(c, V0)).off(RIDER_ANIM).lw(c);
            call_ptr(c, 0x0031_1b20, 0x0013_67f4)?;
            // Animation sequence +0xb0: completion probe object.
            c.g[A0][0] = sx(r32(c, V0).wrapping_add(0xb0));
            c.g[A1][0] = 0;
            call_ptr(c, 0x0014_46a0, 0x0013_6800)?;
            if c.g[V0][0] == 0 {
                return Ok(());
            }
        }
    }
    c.cycles += 5;
    c.g[A0][0] = Addr(r32(c, S0)).off(RIDER).lw(c);
    call_ptr(c, 0x0011_fe98, 0x0013_6810)?;
    c.g[V1][0] = 4;
    let railslide = c.g[V0][0] == c.g[V1][0];
    c.g[A1][0] = 0;
    if railslide {
        c.cycles += 9;
        c.g[V0][0] = Addr(r32(c, S0)).off(RIDER).lw(c);
        c.g[A0][0] = Addr(r32(c, V0)).off(BUMP_RIDER_OWNER).lw(c);
        // RiderBase +0x2b0: railslide substate.
        c.g[A0][0] = sx(r32(c, A0).wrapping_add(0x2b0));
        call_ptr(c, 0x0013_26c8, 0x0013_682c)?;
        c.g[A0][0] = Addr(r32(c, S0)).off(RIDER).lw(c);
        c.g[A1][0] = 7;
        call_ptr(c, 0x0011_fec8, 0x0013_6838)?;
    } else {
        c.cycles += 7;
        c.g[A0][0] = Addr(r32(c, S0)).off(RIDER).lw(c);
        call_ptr(c, 0x0011_5640, 0x0013_6848)?;
        c.g[A0][0] = Addr(r32(c, S0)).off(RIDER).lw(c);
        call_ptr(c, 0x0011_fe98, 0x0013_6850)?;
        c.g[V1][0] = 1;
        let airborne = c.g[V0][0] == c.g[V1][0];
        c.g[A0][0] = Addr(r32(c, S0)).off(RIDER).lw(c);
        if airborne {
            c.cycles += 4;
            c.g[A1][0] = 5;
            call_ptr(c, 0x0011_fec8, 0x0013_6864)?;
        } else {
            c.cycles += 3;
            c.g[A1][0] = 0;
            call_ptr(c, 0x0011_fec8, 0x0013_6874)?;
        }
    }
    c.g[V0][0] = Addr(r32(c, S0)).off(RIDER).lw(c);
    c.cycles += 12;
    c.g[A1][0] = Addr(r32(c, V0)).off(STANCE).lw(c);
    c.g[A0][0] = Addr(r32(c, V0)).off(METRIX).lw(c);
    call_ptr(c, 0x0011_9958, 0x0013_6884)?;
    c.g[A0][0] = Addr(r32(c, S0)).off(RIDER).lw(c);
    c.mov_s(12, 0);
    c.g[A1][0] = 1;
    call_ptr(c, 0x0010_e098, 0x0013_6894)?;
    c.g[A0][0] = Addr(r32(c, S0)).off(RIDER).lw(c);
    c.g[V1][0] = Addr(r32(c, A0)).off(update_trick::UBER_LEVEL).lw(c);
    c.g[V0][0] = ((c.g[V1][0] as i64) < 10) as u64;
    let increment = c.g[V0][0] != 0;
    c.g[V0][0] = sx(r32(c, V1).wrapping_add(1));
    if increment {
        c.cycles += 6;
        Addr(r32(c, A0))
            .off(update_trick::UBER_LEVEL)
            .sw(c, c.g[V0][0]);
        c.g[V1][0] = 10;
        c.g[A0][0] = Addr(r32(c, S0)).off(RIDER).lw(c);
        c.g[V0][0] = Addr(r32(c, A0)).off(update_trick::UBER_LEVEL).lw(c);
        if c.g[V0][0] != c.g[V1][0] {
            return Ok(());
        }
        c.cycles += 3;
        c.g[AT][0] = 0x4270_0000;
        c.mtc1(AT, 0);
        c.swc1(0, r32(c, A0).wrapping_add(update_trick::UBER_TIMER));
    }
    c.cycles += 1;
    Ok(())
}

/// `void AI_ResetRidersAndOrder(AI* ai)` (0x128a10): reset every rider and
/// then put the order mode back to 0.
pub fn ai_reset_riders_and_order(c: &mut Cpu) {
    guest(c, |c| {
        c.cycles += 13;
        let frame = Frame::open(c, 0x20);
        c.g[A1][0] = 0;
        frame.save(c, S0, 0x10);
        frame.save_ra(c, 0);
        c.g[S0][0] = c.g[A0][0];
        callee::AI_RESET_RIDERS.call(c, 0x0012_8a28)?;
        c.g[A0][0] = c.g[S0][0];
        c.g[A1][0] = 0;
        callee::AI_SET_RIDER_ORDER_MODE.call(c, 0x0012_8a34)?;
        frame.restore(c, S0, 0x10);
        frame.restore_ra(c, 0);
        frame.close(c);
        Ok(())
    })
}

/// `SectionMan_FindLogicalSection` (0x22e0e0).
pub(crate) const FIND_LOGICAL_SECTION: u32 = 0x0022_e0e0;

/// `PathData_EmptyHook` (0x26ada0).
pub(crate) const PATH_DATA_EMPTY_HOOK: u32 = 0x0026_ada0;

// ---------------------------------------------------------------------------
// AI_PathDataInitIfEarlySection.

/// `void AI_PathDataInitIfEarlySection(void* p, uchar id)` (0x12a490) — the
/// reference has no name for it: when the logical section that the world's
/// rider manager names at `+0x78` is one of the first 22, initialise the path
/// data.
pub fn ai_path_data_init_if_early_section(c: &mut Cpu) {
    guest(c, |c| {
        c.cycles += 9;
        let frame = Frame::open(c, 0x10);
        let world = gp(c, -0x848);
        c.g[V0][0] = Addr(world).lw(c);
        frame.save_ra(c, 0);
        c.g[V1][0] = Addr(c.g[V0][0] as u32).off(0x84).lw(c);
        c.g[A0][0] = Addr(c.g[V1][0] as u32).off(0x78).lw(c);
        call_ptr(c, FIND_LOGICAL_SECTION, 0x0012_a4a8)?;
        c.g[V0][0] = ((c.g[V0][0] as i64) < 22i64) as u64;
        let early = c.g[V0][0] != 0;
        frame.restore_ra(c, 0);
        if early {
            c.cycles += 4;
            c.g[A0][0] = 0x004d_0000;
            c.g[A0][0] = sx(0x004d_33a0);
            call_ptr(c, PATH_DATA_EMPTY_HOOK, 0x0012_a4c0)?;
            frame.restore_ra(c, 0);
        }
        c.cycles += 2;
        frame.close(c);
        Ok(())
    })
}

// ---------------------------------------------------------------------------
// Rider metrics and AI setup.

/// `void RiderMetrix_ResetStats(RiderMetrix* m)` (0x1175b8): clear the 0xac
/// byte stat block at `+0xfc`, mark `+0x18c` as "no trick" (−1) and carry
/// `+0x1c8` into `+0x198`.
pub fn rider_metrix_reset_stats(c: &mut Cpu) {
    guest(c, |c| {
        c.cycles += 16;
        let frame = Frame::open(c, 0x20);
        c.g[A1][0] = 0;
        frame.save(c, S0, 0x10);
        c.g[A2][0] = 0xac;
        c.g[S0][0] = c.g[A0][0];
        frame.save_ra(c, 0);
        c.g[A0][0] = sx(p(crate::abi::r32(c, S0), 0xfc));
        callee::EA_MEM_SET.call(c, 0x0011_75d8)?;
        let this = crate::abi::r32(c, S0);
        c.g[V1][0] = lw(c, this, 0x1c8);
        c.g[V0][0] = u64::MAX;
        Addr(p(this, 0x18c)).sw(c, c.g[V0][0]);
        Addr(p(this, 0x198)).sw(c, c.g[V1][0]);
        frame.restore(c, S0, 0x10);
        frame.restore_ra(c, 0);
        frame.close(c);
        Ok(())
    })
}

/// `void AI_SetupComputerRiders(cAI* ai)` (0x128958): kill the previous
/// computer riders when there were any, then create a fresh set.
pub fn ai_setup_computer_riders_2(c: &mut Cpu) {
    guest(c, |c| {
        c.cycles += 8;
        let frame = Frame::open(c, 0x20);
        frame.save(c, S0, 0x10);
        frame.save_ra(c, 0);
        c.g[S0][0] = c.g[A0][0];
        let this = crate::abi::r32(c, S0);
        Addr(p(this, 0x94)).sw(c, 0);
        c.g[V0][0] = lw(c, this, 0x88);
        if (c.g[V0][0] as i64) > 0 {
            c.cycles += 2;
            callee::AI_DESTROY_MISSION_RIDERS.call(c, 0x0012_8980)?;
        }
        c.cycles += 6;
        c.g[A0][0] = c.g[S0][0];
        callee::AI_CREATE_COMPUTER_RIDERS.call(c, 0x0012_8988)?;
        frame.restore(c, S0, 0x10);
        frame.restore_ra(c, 0);
        frame.close(c);
        Ok(())
    })
}

/// The three `RiderSpinSub_IsTrickAnim1x` predicates: `kind` is the spin
/// sub-state (`+0x4`) and `trick` the animation id they test for. The
/// animation entry comes from the rider's controller at `+0x58` → `+0x784`.
pub(crate) fn rider_spin_sub_is_trick_anim(c: &mut Cpu, ret: u32, kind: u64, trick: u64) {
    guest(c, |c| {
        c.cycles += 6;
        let frame = Frame::open(c, 0x10);
        frame.save_ra(c, 0);
        let this = crate::abi::arg(c, 0);
        c.g[V0][0] = kind;
        c.g[V1][0] = lw(c, this, 4);
        let same = c.g[V1][0] == c.g[V0][0];
        c.g[A1][0] = 0;
        if same {
            c.cycles += 6;
            c.g[V0][0] = lw(c, this, 0x58);
            c.g[A1][0] = 2;
            let ctrl = crate::abi::r32(c, V0);
            c.g[A0][0] = lw(c, ctrl, 0x784);
            callee::ANIM_CONTROLLER_GET_LAYER_ANIM_ENTRY.call(c, ret)?;
            c.g[V0][0] ^= trick;
            c.g[A1][0] = (c.g[V0][0] < 1) as u64;
        }
        c.cycles += 4;
        frame.restore_ra(c, 0);
        c.g[V0][0] = c.g[A1][0];
        frame.close(c);
        Ok(())
    })
}

/// `int RiderSpinSub_IsTrickAnim12(SpinSub* s)` (0x135eb0): sub-state 2 with
/// animation entry 0x12. Returns 0 instead of `gcc`'s `1` when the entry is
/// not a trick (`v0` is set from `v1`, as the original does).
pub fn rider_spin_sub_is_trick_anim12(c: &mut Cpu) {
    rider_spin_sub_is_trick_anim(c, 0x0013_5ed8, 2, 0x12)
}

/// `int RiderSpinSub_IsTrickAnim13(SpinSub* s)` (0x135ef0): sub-state 4 with
/// animation entry 0x13.
pub fn rider_spin_sub_is_trick_anim13(c: &mut Cpu) {
    rider_spin_sub_is_trick_anim(c, 0x0013_5f18, 4, 0x13)
}

/// `int RiderSpinSub_IsTrickAnim14(SpinSub* s)` (0x135f30): sub-state 4 with
/// animation entry 0x14.
pub fn rider_spin_sub_is_trick_anim14(c: &mut Cpu) {
    rider_spin_sub_is_trick_anim(c, 0x0013_5f58, 4, 0x14)
}

/// `bool RiderGateSub_CanStart(GateSub* g)` (0x12c078): false only when the
/// race is running (mode != 5) and the gate's timer (`g+0x14 -> +0x470`) is
/// still negative.
pub fn rider_gate_sub_can_start(c: &mut Cpu) {
    c.cycles += 8;
    let world = c.lw(gp(c, -0x848)) as u32;
    c.g[A3][0] = c.g[A0][0];
    c.g[A2][0] = 5;
    c.g[V0][0] = c.lw(world.wrapping_add(0x84));
    c.g[V1][0] = c.lw(r32(c, V0).wrapping_add(0xc));
    c.g[A0][0] = c.lw(r32(c, V1));
    let running = c.g[A0][0] != c.g[A2][0];
    c.g[V0][0] = 1;
    if running {
        c.cycles += 6;
        c.g[V1][0] = c.lw(r32(c, A3).wrapping_add(0x14));
        c.f[1] = 0;
        let timer = Addr(r32(c, V1).wrapping_add(0x470)).read_fpu(c);
        c.f[0] = timer.0;
        let ready = FpuF32::ZERO.le(timer);
        abi::set_fcc(c, ready);
        if !ready {
            c.cycles += 2;
            c.g[V0][0] = 0;
            abi::ret(c);
            return;
        }
    }
    c.cycles += 2;
    abi::ret(c);
}

/// The FPU constant the rider-gate timing multiplies the race clock by
/// (1/60: seconds per frame), at `gp_2 - 0x7840`.
pub(crate) const FRAME_SECONDS_GP: i32 = -0x7840;

/// The game-module global (`D_004A28A8`, the world/app pointer).
pub(crate) const GAME_MODULE_GP: i32 = -0x848;

// ---------------------------------------------------------------------------
// Rider gate timing.

/// `bool RiderGateSub_IsStartTimeReached(RiderGateSub* gate)` (0x12c028):
/// only while the race manager's state is 5, true when the race clock
/// (frames × 1/60) has reached the gate's start time (`gate->+0x14 ->
/// +0xb30`). 8 (+10 when racing) + 2 cycles.
pub fn ridergate_sub_is_start_time_reached(c: &mut Cpu) {
    c.cycles += 8;
    let module = c.lw(gp_2(c, GAME_MODULE_GP));
    c.g[A1][0] = c.g[A0][0];
    c.g[A0][0] = 5;
    let world = c.lw(p(module as u32, 0x84));
    let race = c.lw(p(world as u32, 0xc));
    let state = c.lw(race as u32);
    c.g[V1][0] = state;
    c.g[A2][0] = 0;
    let mut reached = 0u64;
    if state == c.g[A0][0] {
        c.cycles += 10;
        let frames = Addr(p(race as u32, 0xc)).read_fpu(c);
        c.f[0] = frames.0;
        c.cvt_s_w(0, 0);
        let seconds = Addr(gp_2(c, FRAME_SECONDS_GP)).read_fpu(c);
        c.f[1] = seconds.0;
        let rider = c.lw(p(r32(c, A1), 0x14));
        c.g[V1][0] = rider;
        c.mul_s(0, 0, 1);
        c.g[A0][0] = c.lw(p(rider as u32, 0xb30));
        c.cvt_w_s(1, 0);
        c.mfc1(2, 1);
        c.g[V0][0] = ((c.g[V0][0] as i64) < (c.g[A0][0] as i64)) as u64;
        reached = c.g[V0][0] ^ 1;
    }
    c.cycles += 2;
    c.g[A2][0] = reached;
    c.g[V0][0] = reached;
    abi::ret(c);
}

/// `void AI_SetupActorRiders(AI* ai, int n)` (0x128998): clear the BE
/// interface, and unless the "computer players" flag is set, store `n` and
/// spawn the computer actor riders.
pub fn ai_setup_actor_riders(c: &mut Cpu) {
    c.cycles += 14;
    let frame = Frame::open(c, 0x30);
    frame.save(c, S0, 0x20);
    frame.save(c, S1, 0x10);
    c.g[S0][0] = c.g[A0][0];
    frame.save_ra(c, 0);
    c.g[S1][0] = c.g[A1][0];
    if call_ptr(c, 0x0014_dc80, 0x0012_89b4).is_err() {
        return;
    }
    c.g[A0][0] = c.g[V0][0];
    c.g[A1][0] = 0;
    if call_ptr(c, 0x0014_dd58, 0x0012_89c0).is_err() {
        return;
    }
    c.g[V1][0] = 0x0053_0000;
    c.g[V0][0] = Addr(p_2(c, V1, 0x5c11)).lb(c);
    if c.g[V0][0] == 0 {
        c.cycles += 4;
        c.sw(p_2(c, S0, 0x94), c.g[S1][0]);
        c.g[A0][0] = c.g[S0][0];
        if callee::AI_CREATE_ACTOR_RIDERS.call(c, 0x0012_89dc).is_err() {
            return;
        }
    }
    frame.restore(c, S0, 0x20);
    c.cycles += 4;
    frame.restore(c, S1, 0x10);
    frame.restore_ra(c, 0);
    frame.close(c);
}

/// `void RiderBoardPressSub_Cancel(RiderBoardPress* self)` (0x131348): cancel
/// a board press, finishing the metric and granting the boost when the press
/// had been held for one or two frames.
pub fn rider_board_press_sub_cancel(c: &mut Cpu) {
    guest(c, |c| {
        c.cycles += 13;
        let frame = Frame::open(c, 0x20);
        frame.save(c, S0, 0x10);
        frame.save_ra(c, 0);
        c.g[RA][0] = sx(0x0013_135c);
        c.g[S0][0] = c.g[A0][0];
        callee::RIDER_BOARD_PRESS_SUB_SETTLE_SLEW.call(c, 0x0013_135c)?;
        c.g[RA][0] = sx(0x0013_1364);
        c.g[A0][0] = c.g[S0][0];
        callee::RIDER_BOARD_PRESS_SUB_FINISH_PRESS.call(c, 0x0013_1364)?;
        c.g[V1][0] = Addr(r32(c, S0)).off(0x14).lw(c);
        c.g[V0][0] = Addr(r32(c, V1)).off(0x330).lw(c);
        c.g[V0][0] = sx(r32(c, V0).wrapping_sub(1));
        c.g[V0][0] = (c.g[V0][0] < 2) as u64;
        if c.g[V0][0] != 0 {
            c.cycles += 7;
            c.g[RA][0] = sx(0x0013_1384);
            c.g[A0][0] = Addr(r32(c, V1)).off(0x790).lw(c);
            callee::RIDER_METRIX_FINISH_BOARD_PRESS.call(c, 0x0013_1384)?;
            c.g[A0][0] = Addr(r32(c, S0)).off(0x14).lw(c);
            c.mov_s(12, 0);
            c.g[RA][0] = sx(0x0013_1394);
            c.g[A1][0] = 1;
            callee::RIDER_ADD_BOOST_2.call(c, 0x0013_1394)?;
        }
        frame.restore(c, S0, 0x10);
        c.cycles += 3;
        frame.restore_ra(c, 0);
        frame.close(c);
        Ok(())
    })
}

/// `float RiderSpinSub_GetSpinHUDBlend(RiderSpinSub* self)` (0x136100): spin
/// amount in turns, clamped to [0, 1], eased by the square root curve.
pub fn rider_spin_sub_get_spin_hud_blend(c: &mut Cpu) {
    c.cycles += 11;
    c.lwc1(3, p(c.g[A0][0] as u32, 0x18));
    c.lwc1(0, gp(c, -0x7304));
    c.g[AT][0] = 0x3f00_0000;
    c.mtc1(AT, 4);
    c.mul_s(0, 3, 0);
    c.add_s(0, 0, 4);
    c.cvt_w_s(1, 0);
    c.cvt_s_w(1, 1);
    c.c_lt_s(0, 1);
    if c.fcc() {
        c.cycles += 3;
        c.g[AT][0] = 0x3f80_0000;
        c.mtc1(AT, 0);
        c.sub_s(1, 1, 0);
    }
    c.cycles += 11;
    c.lwc1(0, gp(c, -0x7300));
    c.lwc1(2, gp(c, -0x72fc));
    c.mul_s(0, 1, 0);
    c.mtc1(0, 1);
    c.sub_s(0, 3, 0);
    c.abs_s(0, 0);
    c.mul_s(0, 0, 2);
    c.sub_s(0, 0, 4);
    c.max_s(0, 0, 1);
    c.add_s(0, 0, 0);
    c.pc = c.g[RA][0] as u32;
}

pub(crate) const ANIM_PLAYER_GET_ANIM_FIELD: u32 = 0x0031_2aa0;

pub(crate) const ANIM_CONTROLLER_SET_ANIM: u32 = 0x0031_28e8;

/// `void RiderPrewindSub_Exit(RiderPrewindSub* s)` (0x12e9b0): nothing to tear
/// down.
pub fn rider_prewind_sub_exit(c: &mut Cpu) {
    c.cycles += 2;
    abi::ret(c);
}

// ---------------------------------------------------------------------------
// RiderWipeoutSub animation selectors: look the current/next animation id up
// in a `.rodata` table and, when it actually changes, restart it through the
// rider's anim controller and rescale its speed.

/// The `RiderWipeoutSub` animation-id table (`.rodata 0x4580a0`): case block to
/// the id it selects.
pub(crate) const SWITCH_TO_ANIM_SET_A_IDS: [(u32, u64); 10] = [
    (0x0012_ddf8, 0x16a),
    (0x0012_de00, 0x16b),
    (0x0012_de08, 0x16c),
    (0x0012_de10, 0x16d),
    (0x0012_de18, 0x16e),
    (0x0012_de20, 0x16f),
    (0x0012_de28, 0x170),
    (0x0012_de30, 0x171),
    (0x0012_de38, 0x172),
    (0x0012_de40, 0x173),
];

/// `void RiderWipeoutSub_SwitchToAnimSetA(RiderWipeoutSub* w)` (0x12dd98):
/// pick animation set A's id for the rider's current animation and, if that is
/// not what is playing, restart it at speed -1 and update the anim speed.
pub fn rider_wipeout_sub_switch_to_anim_set_a(c: &mut Cpu) {
    guest(c, |c| {
        let mut pc = c.pc as u32;
        loop {
            match pc {
                0x0012_dd98 => {
                    c.cycles += 14;
                    let frame = Frame::open(c, 0x20);
                    c.g[A1][0] = 0x2;
                    frame.save(c, 16, 0x10);
                    frame.save_ra(c, 0);
                    c.g[S0][0] = c.g[A0][0];
                    c.g[V0][0] = Addr(c.g[S0][0] as u32).off(0x80).lw(c);
                    c.g[A0][0] = Addr(c.g[V0][0] as u32).off(0x784).lw(c);
                    call_ptr(c, ANIM_PLAYER_GET_ANIM_FIELD, 0x0012_ddb8)?;
                    c.g[V1][0] = Addr(c.g[S0][0] as u32).off(0x80).lw(c);
                    c.g[A1][0] = c.g[V0][0];
                    c.g[V0][0] = Addr(c.g[V1][0] as u32).off(0x150).lw(c);
                    c.g[V0][0] = c.g[V0][0] ^ 0x1;
                    let same = c.g[V0][0] == 0;
                    c.g[A2][0] = c.g[A1][0];
                    pc = if same { 0x0012_de48 } else { 0x0012_ddd0 };
                }
                0x0012_ddd0 => {
                    c.cycles += 4;
                    c.g[V1][0] = sx((c.g[A1][0] as u32).wrapping_sub(0x175));
                    c.g[V0][0] = (c.g[V1][0] < 0xfu64) as u64;
                    let out = c.g[V0][0] == 0;
                    c.g[V0][0] = 0x46_0000;
                    pc = if out { 0x0012_de4c } else { 0x0012_dde0 };
                }
                0x0012_dde0 => {
                    c.cycles += 6;
                    c.g[V1][0] = sx((c.g[V1][0] as u32) << 2);
                    c.g[V0][0] = sx((c.g[V0][0] as u32).wrapping_sub(0x7f60));
                    c.g[V1][0] = sx((c.g[V1][0] as u32).wrapping_add(c.g[V0][0] as u32));
                    let target = Addr(c.g[V1][0] as u32).lw(c) as u32;
                    c.g[A0][0] = sx(target);
                    pc = match SWITCH_TO_ANIM_SET_A_IDS.iter().find(|e| e.0 == target) {
                        Some(e) => {
                            c.cycles += 2;
                            c.g[A1][0] = e.1;
                            0x0012_de4c
                        }
                        // The table's 0x17f entry keeps the id unchanged.
                        None if target == 0x0012_de4c => 0x0012_de4c,
                        None => {
                            c.jump_out(target, 0x0012_dd98, 0x0012_de80);
                            return Ok(());
                        }
                    };
                }
                0x0012_ddf8 | 0x0012_de00 | 0x0012_de08 | 0x0012_de10 | 0x0012_de18
                | 0x0012_de20 | 0x0012_de28 | 0x0012_de30 | 0x0012_de38 | 0x0012_de40 => {
                    c.cycles += 2;
                    let id = SWITCH_TO_ANIM_SET_A_IDS
                        .iter()
                        .find(|e| e.0 == pc)
                        .unwrap()
                        .1;
                    c.g[A1][0] = id;
                    pc = 0x0012_de4c;
                }
                0x0012_de48 => {
                    c.cycles += 1;
                    c.g[A1][0] = 0x174;
                    pc = 0x0012_de4c;
                }
                0x0012_de4c => {
                    c.cycles += 2;
                    let same = c.g[A1][0] == c.g[A2][0];
                    c.g[A2][0] = 0;
                    pc = if same { 0x0012_de70 } else { 0x0012_de54 };
                }
                0x0012_de54 => {
                    c.cycles += 7;
                    c.g[V0][0] = Addr(c.g[S0][0] as u32).off(0x80).lw(c);
                    c.g[AT][0] = 0xffff_ffff_bf80_0000;
                    c.mtc1(AT, 12);
                    c.g[A0][0] = Addr(c.g[V0][0] as u32).off(0x784).lw(c);
                    call_ptr(c, ANIM_CONTROLLER_SET_ANIM, 0x0012_de68)?;
                    c.g[A0][0] = c.g[S0][0];
                    callee::RIDER_WIPEOUT_UPDATE_ANIM_SPEED.call(c, 0x0012_de70)?;
                    pc = 0x0012_de70;
                }
                0x0012_de70 => {
                    c.cycles += 4;
                    let frame = Frame { size: 0x20 };
                    frame.restore(c, 16, 0x10);
                    frame.restore_ra(c, 0);
                    let ra = c.g[RA][0] as u32;
                    c.g[SP][0] = sx((c.g[SP][0] as u32).wrapping_add(0x20));
                    c.pc = ra;
                    return Ok(());
                }
                _ => {
                    c.jump_out(pc, 0x0012_dd98, 0x0012_de80);
                    return Ok(());
                }
            }
        }
    })
}

/// `RiderWipeoutSub_PlayEndAnimA` (0x12df48): pick the end-animation id for the
/// rider's current animation (table `.rodata 0x458110`) and, if it changes,
/// restart it at speed -1.
pub fn rider_wipeout_sub_play_end_anim_a(c: &mut Cpu) {
    guest(c, |c| {
        let mut pc = c.pc as u32;
        loop {
            match pc {
                0x0012_df48 => {
                    c.cycles += 13;
                    let frame = Frame::open(c, 0x20);
                    c.g[A1][0] = 0x2;
                    frame.save(c, 16, 0x10);
                    frame.save_ra(c, 0);
                    c.g[S0][0] = c.g[A0][0];
                    c.g[V0][0] = Addr(c.g[S0][0] as u32).off(0x80).lw(c);
                    c.g[A0][0] = Addr(c.g[V0][0] as u32).off(0x784).lw(c);
                    call_ptr(c, ANIM_PLAYER_GET_ANIM_FIELD, 0x0012_df68)?;
                    c.g[A1][0] = c.g[V0][0];
                    c.g[V1][0] = sx((c.g[A1][0] as u32).wrapping_sub(0x16a));
                    c.g[V0][0] = (c.g[V1][0] < 0x1au64) as u64;
                    let out = c.g[V0][0] == 0;
                    c.g[A2][0] = c.g[A1][0];
                    pc = if out { 0x0012_dfe4 } else { 0x0012_df7c };
                }
                0x0012_df7c => {
                    c.cycles += 7;
                    c.g[V0][0] = 0x46_0000;
                    c.g[V1][0] = sx((c.g[V1][0] as u32) << 2);
                    c.g[V0][0] = sx((c.g[V0][0] as u32).wrapping_sub(0x7ef0));
                    c.g[V1][0] = sx((c.g[V1][0] as u32).wrapping_add(c.g[V0][0] as u32));
                    let target = Addr(c.g[V1][0] as u32).lw(c) as u32;
                    c.g[A0][0] = sx(target);
                    pc = match target {
                        0x0012_df98 => 0x0012_df98,
                        0x0012_dfa0 => 0x0012_dfa0,
                        0x0012_dfa8 => 0x0012_dfa8,
                        0x0012_dfb0 => 0x0012_dfb0,
                        0x0012_dfb8 => 0x0012_dfb8,
                        0x0012_dfc0 => 0x0012_dfc0,
                        0x0012_dfc8 => 0x0012_dfc8,
                        0x0012_dfd0 => 0x0012_dfd0,
                        0x0012_dfd8 => 0x0012_dfd8,
                        0x0012_dfe0 => 0x0012_dfe0,
                        0x0012_dfe4 => 0x0012_dfe4,
                        _ => {
                            c.jump_out(target, 0x0012_df48, 0x0012_e010);
                            return Ok(());
                        }
                    };
                }
                0x0012_df98 | 0x0012_dfa0 | 0x0012_dfa8 | 0x0012_dfb0 | 0x0012_dfb8
                | 0x0012_dfc0 | 0x0012_dfc8 | 0x0012_dfd0 | 0x0012_dfd8 => {
                    c.cycles += 2;
                    let id = match pc {
                        0x0012_df98 => 0x185,
                        0x0012_dfa0 => 0x186,
                        0x0012_dfa8 => 0x187,
                        0x0012_dfb0 => 0x188,
                        0x0012_dfb8 => 0x189,
                        0x0012_dfc0 => 0x18a,
                        0x0012_dfc8 => 0x18b,
                        0x0012_dfd0 => 0x18c,
                        _ => 0x18d,
                    };
                    c.g[A1][0] = id;
                    pc = 0x0012_dfe4;
                }
                0x0012_dfe0 => {
                    c.cycles += 1;
                    c.g[A1][0] = 0x18e;
                    pc = 0x0012_dfe4;
                }
                0x0012_dfe4 => {
                    c.cycles += 2;
                    let same = c.g[A1][0] == c.g[A2][0];
                    c.g[A2][0] = 0;
                    pc = if same { 0x0012_e000 } else { 0x0012_dfec };
                }
                0x0012_dfec => {
                    c.cycles += 5;
                    c.g[V0][0] = Addr(c.g[S0][0] as u32).off(0x80).lw(c);
                    c.g[AT][0] = 0xffff_ffff_bf80_0000;
                    c.mtc1(AT, 12);
                    c.g[A0][0] = Addr(c.g[V0][0] as u32).off(0x784).lw(c);
                    call_ptr(c, ANIM_CONTROLLER_SET_ANIM, 0x0012_e000)?;
                    pc = 0x0012_e000;
                }
                0x0012_e000 => {
                    c.cycles += 4;
                    let frame = Frame { size: 0x20 };
                    frame.restore(c, 16, 0x10);
                    frame.restore_ra(c, 0);
                    let ra = c.g[RA][0] as u32;
                    c.g[SP][0] = sx((c.g[SP][0] as u32).wrapping_add(0x20));
                    c.pc = ra;
                    return Ok(());
                }
                _ => {
                    c.jump_out(pc, 0x0012_df48, 0x0012_e010);
                    return Ok(());
                }
            }
        }
    })
}

