            c.g[A0][0] = c.lw(at(c, S1, RIDER));
            call_ptr(c, 0x0011_5b58, 0x0013_1870)?; // Rider_UpdateTimedEventAnim
            c.g[A0][0] = c.lw(at(c, S1, RIDER));
            call_ptr(c, 0x0011_5d48, 0x0013_1878)?; // Rider_UpdateIdleLookAnim
            c.g[V0][0] = c.lw(at(c, S1, RIDER));
            c.g[A1][0] = 0x2;
