            c.g[AT][0] = 0xffffffffbf800000;
            c.mtc1(1, 12);
            c.g[A2][0] = 0u64;
            c.g[A0][0] = c.lw((c.g[V0][0] as u32).wrapping_add(0x784));
            call_ptr(c, 0x003128e8, 0x0012bf34)?;
