    macro_rules! load_state_tests {
        ($(($test:ident, $func:ident, $shard:ident, $addr:ident, $salt:expr)),* $(,)?) => {
            $(
                #[test]
                fn $test() {
                    check(ee::$shard::$addr, $func, SEEDS_2, &|c, seed| {
                        virtual_setup(c, seed, $salt, 0x10);
                    });
                }
            )*
        };
    }

